const e="n4-test-2",t="N4",o="JLPT N4 Practice Test 2",n={vocabulary:{timeLimit:25,questions:[{id:"v1",type:"kanji-reading",question:"【荷物】を運んでください。",options:["きもつ","にもつ","なんもつ","ほもつ"],correctAnswer:1,explanation:"荷物 (にもつ) means 'luggage' or 'baggage'."},{id:"v2",type:"kanji-reading",question:"【社長】は明日帰ります。",options:["しゃちょう","しちょう","しゃちゅ","しゃちょ"],correctAnswer:0,explanation:"社長 (しゃちょう) means 'company president'."},{id:"v3",type:"kanji-reading",question:"【複雑】な問題ですね。",options:["ふざつ","ふくさつ","ふくざつ","ふくざん"],correctAnswer:2,explanation:"複雑 (ふくざつ) means 'complicated'."},{id:"v4",type:"kanji-reading",question:"【安全】に気をつけてください。",options:["あんぜん","あんせん","あぜん","あんちゅう"],correctAnswer:0,explanation:"安全 (あんぜん) means 'safety'."},{id:"v5",type:"kanji-reading",question:"新しい【工場】ができました。",options:["こば","こうじょう","こじょう","こうちょう"],correctAnswer:1,explanation:"工場 (こうじょう) means 'factory'."},{id:"v6",type:"kanji-reading",question:"【注意】して聞いてください。",options:["じゅうい","ちゅうい","ちゅい","しゅうい"],correctAnswer:1,explanation:"注意 (ちゅうい) means 'attention' or 'warning'."},{id:"v7",type:"kanji-reading",question:"【説明】がわかりません。",options:["せつめ","せつみょう","せつめい","しつめい"],correctAnswer:2,explanation:"説明 (せつめい) means 'explanation'."},{id:"v8",type:"orthography",question:"【りゆう】を教えてください。",options:["理由","理有","利由","里由"],correctAnswer:0,explanation:"理由 (りゆう) is the kanji for reason."},{id:"v9",type:"orthography",question:"【けんきゅう】しています。",options:["研九","勉強","研究","研求"],correctAnswer:2,explanation:"研究 (けんきゅう) is the kanji for research."},{id:"v10",type:"orthography",question:"【けいざい】のニュースを見ます。",options:["経済","経剤","経験","経才"],correctAnswer:0,explanation:"経済 (けいざい) is the kanji for economy."},{id:"v11",type:"orthography",question:"【しなもの】を並べます。",options:["品者","品物","味物","品本"],correctAnswer:1,explanation:"品物 (しなもの) is the kanji for goods/articles."},{id:"v12",type:"orthography",question:"【けしき】がきれいです。",options:["気色","花色","景色","風色"],correctAnswer:2,explanation:"景色 (けしき) is the kanji for scenery."},{id:"v13",type:"orthography",question:"【いけん】を言ってください。",options:["意建","意見","異見","以見"],correctAnswer:1,explanation:"意見 (いけん) is the kanji for opinion."},{id:"v14",type:"context",question:"パソコンが（　　）ので、修理に出しました。",options:["おれた","こわれた","やぶれた","われた"],correctAnswer:1,explanation:"壊れる (こわれる) is used for machines breaking."},{id:"v15",type:"context",question:"お湯を（　　）お茶をいれます。",options:["わかして","やいて","にる","あげて"],correctAnswer:0,explanation:"お湯を沸かす means 'to boil water'."},{id:"v16",type:"context",question:"この（　　）は、1日に3回飲んでください。",options:["おちゃ","ジュース","くすり","ごはん"],correctAnswer:2,explanation:"Medicine (くすり) is prescribed to be taken (飲んで) a certain number of times a day."},{id:"v17",type:"context",question:"田中さんに（　　）をもらって、うれしかったです。",options:["おつり","プレゼント","にもつ","じしょ"],correctAnswer:1,explanation:"You receive a present (プレゼント) and feel happy."},{id:"v18",type:"context",question:"（　　）、このペンを貸していただけませんか。",options:["おつかれさまでした","おねがいします","すみませんが","どうぞ"],correctAnswer:2,explanation:"すみませんが is used to interrupt or ask a favor."},{id:"v19",type:"context",question:"ここは（　　）から、気をつけてください。",options:["あんぜんだ","きけんだ","べんりだ","ふべんだ"],correctAnswer:1,explanation:"You need to be careful (気をつけて) because it is dangerous (きけんだ)."},{id:"v20",type:"context",question:"旅行の（　　）はもう終わりましたか。",options:["じゅんび","けいけん","じゅぎょう","しゅみ"],correctAnswer:0,explanation:"準備 (じゅんび) means preparation, often for a trip."},{id:"v21",type:"context",question:"このカレーの（　　）はどうですか。辛いですか。",options:["におい","あじ","ねだん","いろ"],correctAnswer:1,explanation:"味 (あじ) means taste/flavor."},{id:"v22",type:"context",question:"大学に（　　）するために、たくさん勉強します。",options:["ごうかく","しっぱい","そつぎょう","けっこん"],correctAnswer:0,explanation:"合格する (ごうかくする) means to pass (an exam/entrance)."},{id:"v23",type:"context",question:"髪が伸びたので、（　　）へ行きます。",options:["びょういん","とこや","ぎんこう","きっさてん"],correctAnswer:1,explanation:"床屋 (とこや) or 美容院 (びよういん) is a barber/hair salon. 病院 (びょういん) is hospital."},{id:"v24",type:"paraphrase",question:"【遠慮しないで】食べてください。",options:["急いで食べてください。","ゆっくり食べてください。","無理しないで食べてください。","気を遣わないで食べてください。"],correctAnswer:3,explanation:"遠慮する means to hold back / be reserved. 遠慮しないで means 'Don't hold back / Don't worry about us' (気を遣わないで)."},{id:"v25",type:"paraphrase",question:"山田さんは【おしゃべり】な人です。",options:["山田さんはよく話す人です。","山田さんはよく笑う人です。","山田さんは静かな人です。","山田さんは面白い人です。"],correctAnswer:0,explanation:"おしゃべり means talkative (よく話す)."},{id:"v26",type:"paraphrase",question:"明日のパーティーには【必ず】来てください。",options:["できれば来てください。","絶対に来てください。","早く来てください。","無理しないで来てください。"],correctAnswer:1,explanation:"必ず (かならず) means surely/without fail, similar to 絶対に (ぜったいに)."},{id:"v27",type:"paraphrase",question:"このパソコンは【複雑です】。",options:["このパソコンは使い方が簡単です。","このパソコンは使い方が難しいです。","このパソコンは新しいです。","このパソコンは便利です。"],correctAnswer:1,explanation:"複雑 (ふくざつ) means complicated, meaning it's hard to use (難しい)."},{id:"v28",type:"paraphrase",question:"【そっくりな】兄弟ですね。",options:["とても似ている兄弟ですね。","とても違う兄弟ですね。","仲がいい兄弟ですね。","背が高い兄弟ですね。"],correctAnswer:0,explanation:"そっくり means exactly alike / resembling closely (とても似ている)."},{id:"v29",type:"paraphrase",question:"約束を【破って】はいけません。",options:["約束を忘れてはいけません。","約束を守らなくてはいけません。","約束を変えてはいけません。","約束をしてはいけません。"],correctAnswer:1,explanation:"約束を破る means to break a promise, so you must not do it, which means you must keep it (守らなくてはいけません)."},{id:"v30",type:"paraphrase",question:"【最近】、運動を始めました。",options:["先週、運動を始めました。","ずっと前に運動を始めました。","このごろ、運動を始めました。","明日から運動を始めます。"],correctAnswer:2,explanation:"最近 (さいきん) means lately/recently, similar to このごろ."}]},grammar:{timeLimit:25,questions:[{id:"g1",type:"grammar-fill",question:"明日、雨が（　　）出かけません。",options:["降ると","降れば","降ったら","降っても"],correctAnswer:2,explanation:"〜たら is a conditional ('If it rains tomorrow, I won't go out'). 降れば is also correct theoretically, but 降ったら is most common for specific future conditions with volitional/intentional consequence."},{id:"g2",type:"grammar-fill",question:"この漢字の（　　）方を教えてください。",options:["読む","読んで","読み","読んだ"],correctAnswer:2,explanation:"〜方 (how to) attaches to the verb stem (読み)."},{id:"g3",type:"grammar-fill",question:"私は日本の音楽に興味が（　　）。",options:["あります","います","します","なります"],correctAnswer:0,explanation:"興味がある means 'to have an interest'."},{id:"g4",type:"grammar-fill",question:"先生は学生に宿題を（　　）。",options:["させました","されました","してあげました","してくれました"],correctAnswer:0,explanation:"Causative させる (made the students do homework)."},{id:"g5",type:"grammar-fill",question:"あのレストランは、おいしい（　　）、安いです。",options:["し","から","ので","のに"],correctAnswer:0,explanation:"〜し is used to list multiple reasons/features (it is delicious, AND cheap)."},{id:"g6",type:"grammar-fill",question:"窓が（　　）あります。",options:["開いて","開けて","開く","開ける"],correctAnswer:1,explanation:"〜てあります expresses a state that resulted from someone's intentional action, taking a transitive verb (開けて)."},{id:"g7",type:"grammar-fill",question:"お金がないので、カメラを買うのを（　　）にしました。",options:["やめる","やめて","やめた","やめない"],correctAnswer:0,explanation:"〜ことにする (to decide to do) requires dictionary form (やめる)."},{id:"g8",type:"grammar-fill",question:"山田さんに荷物を持た（　　）。",options:["掃除しました","掃除させました","掃除させられました","掃除してくれました"],correctAnswer:2,explanation:"させられる is the causative-passive (was made to clean the room by my mother)."},{id:"g9",type:"grammar-fill",question:"もっと早く（　　）ばよかったです。",options:["起きれ","起きる","起きた","起きない"],correctAnswer:0,explanation:"起きれば (conditional form of 起きる) + よかったです means 'I wish I had woken up'."},{id:"g10",type:"grammar-fill",question:"この本は面白（　　）ですね。",options:["そう","よう","みたい","らしい"],correctAnswer:0,explanation:"Adjective stem + そうです expresses appearance (looks interesting)."},{id:"g11",type:"grammar-fill",question:`次の文の ★ に入る最もよいものを一つ選びなさい。
私 ___ ___ ★ ___ を ___ します。`,options:["は","母","の仕事","手伝い"],correctAnswer:3,explanation:"The correct order is: 私は母の仕事を手伝います。 The star is '手伝い'."},{id:"g12",type:"grammar-fill",question:"田中 ___ ___ ★ ___ から ___ と言っていました。",options:["さん","行く","は","言ってい"],correctAnswer:1,explanation:"The correct order is: 田中さんは行くと言っていました。 The star is '行く'."},{id:"g13",type:"grammar-fill",question:"きのう ___ ___ ★ ___ たら ___ になりました。",options:["薬","を","飲ん","元気"],correctAnswer:2,explanation:"The correct order is: きのう薬を飲んだら元気になりました。 The star is '飲ん'."},{id:"g14",type:"grammar-fill",question:"あの ___ ___ ★ ___ そう ___ ね。",options:["ケーキ","は","美味し","です"],correctAnswer:3,explanation:"The correct order is: あのケーキは美味しそうですね。 The star is 'です'."},{id:"g15",type:"grammar-fill",question:"辞書 ___ ___ ★ ___ も ___ ですか。",options:["から","先生","借りて","を"],correctAnswer:2,explanation:"The correct order is: 先生から辞書を借りてもいいですか。 The star is '借りて'."},{id:"g16",type:"grammar-fill",question:`文章を読んで、（１）に入る言葉を選びなさい。
私の夢は将来、自分の店を（１）ことです。`,options:["持つ","持って","持った","持たない"],correctAnswer:0,explanation:"こと nominalizes the dictionary form (持つこと = to have/own)."},{id:"g17",type:"grammar-fill",question:`（２）に入る言葉を選びなさい。
そのために、今レストランで働き（２）料理を勉強しています。`,options:["ながら","てから","たり","たあとで"],correctAnswer:0,explanation:"〜ながら expresses simultaneous actions (studying while working)."},{id:"g18",type:"grammar-fill",question:`（３）に入る言葉を選びなさい。
料理を作るのは大変ですが、お客さんに「おいしい」と（３）、とてもうれしいです。`,options:["言うと","言ったら","言われると","言わせると"],correctAnswer:2,explanation:"Passive form 言われる (to be told). 'When I am told...'"},{id:"g19",type:"grammar-fill",question:`（４）に入る言葉を選びなさい。
いつか、（４）国で日本料理の店を作りたいです。`,options:["私の","自分の","あの","その"],correctAnswer:1,explanation:"自分の国 means 'my own country'."},{id:"g20",type:"grammar-fill",question:`（５）に入る言葉を選びなさい。
店を作る（５）は、たくさんお金がかかります。`,options:["の","こと","ため","ように"],correctAnswer:0,explanation:"の nominalizes the clause to be the topic (店を作るのは)."},{id:"g21",type:"grammar-fill",question:`（６）に入る言葉を選びなさい。
（６）、一生懸命働いて、お金を貯めています。`,options:["だから","しかし","すると","ところが"],correctAnswer:0,explanation:"だから (Therefore) connects the reason (needs money) to the action (saving money)."},{id:"g22",type:"grammar-fill",question:`（７）に入る言葉を選びなさい。
両親も私の夢を（７）くれます。`,options:["応援して","応援させ","応援され","応援する"],correctAnswer:0,explanation:"〜てくれる means someone does a favor for you (cheers me on)."},{id:"g23",type:"grammar-fill",question:`（８）に入る言葉を選びなさい。
夢が（８）ように、これからも頑張ります。`,options:["かなう","かなえる","かなって","かなった"],correctAnswer:0,explanation:"夢がかなう (intransitive) + ように (so that my dream will come true)."}]},reading:{timeLimit:55,passages:[{id:"p1",text:"私は昨日、スーパーで買い物をしました。りんごとバナナを買うつもりでしたが、バナナが高かったので、りんごとみかんを買いました。全部で800円でした。帰りにケーキ屋に寄って、ケーキを3つ買いました。",questions:[{id:"r1",type:"reading-comprehension",question:"この人は昨日、スーパーで何を買いましたか。",options:["りんごとバナナ","りんごとみかん","バナナとみかん","ケーキとみかん"],correctAnswer:1,explanation:"The text says 'バナナが高かったので、りんごとみかんを買いました' (Banana was expensive, so I bought apple and mandarin orange)."},{id:"r2",type:"reading-comprehension",question:"スーパーのあとでどこへ行きましたか。",options:["家","果物屋","ケーキ屋","コンビニ"],correctAnswer:2,explanation:"The text says '帰りにケーキ屋に寄って' (On the way back, I stopped at a cake shop)."}]},{id:"p2",text:"日本人はよく「すみません」と言います。人に謝る時だけでなく、お礼を言う時や、人に呼びかける時にも使います。例えば、レストランで店員を呼ぶ時、「すみません」と言います。外国人にとって、少し難しいかもしれません。",questions:[{id:"r3",type:"reading-comprehension",question:"日本人はどんな時に「すみません」と言いますか。",options:["謝る時だけ","お礼を言う時だけ","謝る時やお礼を言う時など","店員を呼ぶ時だけ"],correctAnswer:2,explanation:"The text says '謝る時だけでなく、お礼を言う時や、人に呼びかける時にも使います' (Not only when apologizing, but also when thanking or calling someone)."},{id:"r4",type:"reading-comprehension",question:"外国人にとって、何が難しいかもしれませんか。",options:["日本語の勉強","日本料理を食べること","「すみません」のいろいろな使い方","レストランで注文すること"],correctAnswer:2,explanation:"The text implies that the various usages of 'すみません' might be difficult for foreigners."}]},{id:"p3",text:`【夏休みのアルバイト募集】
・仕事：コンビニのレジ、商品の並べ方など
・時間：午後1時〜午後6時（月・水・金）
・時給：1,000円
・条件：日本語で日常会話ができる人。高校生は不可。
※電話で連絡してから、履歴書（写真付き）を持ってきてください。`,questions:[{id:"r5",type:"reading-comprehension",question:"アルバイトの時間は1週間に何時間ですか。",options:["5時間","10時間","15時間","20時間"],correctAnswer:2,explanation:"1 to 6 PM is 5 hours. 3 days a week (Mon, Wed, Fri) = 15 hours."},{id:"r6",type:"reading-comprehension",question:"このアルバイトができるのはどんな人ですか。",options:["日本語が話せる高校生","日本語で日常会話ができる大学生","日本語が全く話せない人","毎日働ける人"],correctAnswer:1,explanation:"The conditions require daily conversation in Japanese, and high school students are not allowed (高校生は不可), so a university student (大学生) fits."},{id:"r7",type:"reading-comprehension",question:"応募する時、まず何をしなければなりませんか。",options:["店へ行く","履歴書を買う","電話をする","写真を撮る"],correctAnswer:2,explanation:"The text says '電話で連絡してから' (After calling/contacting by phone...)."}]}]}},i={id:e,level:t,title:o,sections:n};export{i as default,e as id,t as level,n as sections,o as title};
